import 'package:flutter/material.dart';

import 'data/open_backend.dart';
import 'main.dart' as ui;

class SettingsScreen extends StatefulWidget {
  const SettingsScreen({super.key, this.onSignedOut});
  final VoidCallback? onSignedOut;
  @override State<SettingsScreen> createState()=>_SettingsScreenState();
}

class _SettingsScreenState extends State<SettingsScreen>{
  bool keyNotifications=true, matchNotifications=true, messageNotifications=true;
  bool onlineVisible=true, distanceVisible=true, discoverVisible=true;
  Future<void> _signOut()async{final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Çıkış yapılsın mı?'),content:const Text('Hesabından çıkış yapacaksın.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Vazgeç')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Çıkış yap'))]));if(ok==true){await OpenBackend.instance.signOut();if(!mounted)return;widget.onSignedOut?.call();Navigator.of(context).popUntil((r)=>r.isFirst);}}
  void _soon(String title)=>ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$title yakında aktif olacak.')));
  @override Widget build(BuildContext context)=>Scaffold(backgroundColor:const Color(0xfff7f7f4),body:SafeArea(child:ListView(padding:const EdgeInsets.fromLTRB(18,12,18,32),children:[
    Row(children:[_circle(Icons.arrow_back_rounded,()=>Navigator.pop(context)),const Expanded(child:Text('Ayarlar',textAlign:TextAlign.center,style:TextStyle(fontSize:28,fontWeight:FontWeight.w900,letterSpacing:-.8))),const SizedBox(width:48)]),
    const SizedBox(height:24),_Section(title:'Hesap',children:[_Tile(Icons.person_outline_rounded,'Hesap bilgileri','Telefon, e-posta ve hesap bilgilerin',()=>_soon('Hesap bilgileri')),_Tile(Icons.lock_outline_rounded,'Şifre ve giriş','Giriş yöntemlerini yönet',()=>_soon('Şifre ve giriş')),_Tile(Icons.pause_circle_outline_rounded,'Hesabı dondur','Profilini geçici olarak gizle',()=>_soon('Hesabı dondurma'))]),
    _Section(title:'Keşfet tercihleri',children:[_Tile(Icons.tune_rounded,'Aradığın kişiler','Kimleri görmek istediğini seç',()=>_soon('Keşfet tercihleri')),_Tile(Icons.cake_outlined,'Yaş aralığı','Tercih ettiğin yaş aralığı',()=>_soon('Yaş aralığı')),_Tile(Icons.near_me_outlined,'Maksimum mesafe','Yakınındaki profilleri ayarla',()=>_soon('Mesafe ayarı')),_Tile(Icons.location_on_outlined,'Konum','Keşfet konumunu yönet',()=>_soon('Konum'))]),
    _Section(title:'Bildirimler',children:[_SwitchTile(Icons.key_outlined,'Yeni anahtarlar',keyNotifications,(v)=>setState(()=>keyNotifications=v)),_SwitchTile(Icons.auto_awesome_rounded,'Eşleşmeler',matchNotifications,(v)=>setState(()=>matchNotifications=v)),_SwitchTile(Icons.chat_bubble_outline_rounded,'Mesajlar',messageNotifications,(v)=>setState(()=>messageNotifications=v))]),
    _Section(title:'Gizlilik',children:[_SwitchTile(Icons.circle_outlined,'Çevrimiçi durum',onlineVisible,(v)=>setState(()=>onlineVisible=v)),_SwitchTile(Icons.social_distance_rounded,'Mesafemi göster',distanceVisible,(v)=>setState(()=>distanceVisible=v)),_SwitchTile(Icons.visibility_outlined,'Keşfette görün',discoverVisible,(v)=>setState(()=>discoverVisible=v)),_Tile(Icons.block_rounded,'Engellenen hesaplar','Engellediğin kişileri yönet',()=>_soon('Engellenen hesaplar'))]),
    _Section(title:'Uygulama',children:[_Tile(Icons.language_rounded,'Dil','Türkçe',()=>_soon('Dil seçimi')),_Tile(Icons.dark_mode_outlined,'Görünüm','Açık tema',()=>_soon('Tema')),_Tile(Icons.vibration_rounded,'Titreşim ve ses','Uygulama geri bildirimleri',()=>_soon('Titreşim ve ses'))]),
    _Section(title:'Destek',children:[_Tile(Icons.help_outline_rounded,'Yardım ve destek','Soruların için bize ulaş',()=>_soon('Yardım')),_Tile(Icons.feedback_outlined,'Geri bildirim','Open’ı geliştirmemize yardım et',()=>_soon('Geri bildirim')),_Tile(Icons.description_outlined,'Kullanım koşulları','',()=>_soon('Kullanım koşulları')),_Tile(Icons.privacy_tip_outlined,'Gizlilik politikası','',()=>_soon('Gizlilik politikası'))]),
    const SizedBox(height:4),SizedBox(height:58,child:OutlinedButton.icon(onPressed:_signOut,icon:const Icon(Icons.logout_rounded),label:const Text('Çıkış yap',style:TextStyle(fontWeight:FontWeight.w800)),style:OutlinedButton.styleFrom(foregroundColor:Colors.red,side:BorderSide(color:Colors.red.withValues(alpha:.18)),backgroundColor:Colors.white,shape:RoundedRectangleBorder(borderRadius:BorderRadius.circular(20))))),
    const SizedBox(height:14),TextButton(onPressed:()=>_soon('Hesap silme'),child:const Text('Hesabımı sil',style:TextStyle(color:Colors.red,fontWeight:FontWeight.w700))),const Center(child:Text('Open',style:TextStyle(color:ui.OpenApp.muted,fontSize:12)))
  ])));
  Widget _circle(IconData icon,VoidCallback tap)=>InkWell(onTap:tap,borderRadius:BorderRadius.circular(30),child:Container(width:48,height:48,decoration:BoxDecoration(color:Colors.white,shape:BoxShape.circle,boxShadow:[BoxShadow(color:Colors.black.withValues(alpha:.06),blurRadius:14)]),child:Icon(icon)));
}

class _Section extends StatelessWidget{const _Section({required this.title,required this.children});final String title;final List<Widget> children;@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.only(bottom:22),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Padding(padding:const EdgeInsets.fromLTRB(6,0,6,9),child:Text(title,style:const TextStyle(fontSize:15,fontWeight:FontWeight.w900))),Container(decoration:BoxDecoration(color:Colors.white,borderRadius:BorderRadius.circular(25),boxShadow:[BoxShadow(color:Colors.black.withValues(alpha:.035),blurRadius:18)]),child:Column(children:[for(var i=0;i<children.length;i++)...[children[i],if(i<children.length-1)const Divider(height:1,indent:64,endIndent:16)]]))]));}
class _Tile extends StatelessWidget{const _Tile(this.icon,this.title,this.subtitle,this.tap);final IconData icon;final String title,subtitle;final VoidCallback tap;@override Widget build(BuildContext c)=>InkWell(onTap:tap,borderRadius:BorderRadius.circular(22),child:Padding(padding:const EdgeInsets.symmetric(horizontal:14,vertical:13),child:Row(children:[_SettingIcon(icon),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(title,style:const TextStyle(fontSize:15,fontWeight:FontWeight.w800)),if(subtitle.isNotEmpty)...[const SizedBox(height:2),Text(subtitle,style:const TextStyle(fontSize:12,color:ui.OpenApp.muted))]])),const Icon(Icons.chevron_right_rounded,color:ui.OpenApp.muted)])));}
class _SwitchTile extends StatelessWidget{const _SwitchTile(this.icon,this.title,this.value,this.changed);final IconData icon;final String title;final bool value;final ValueChanged<bool> changed;@override Widget build(BuildContext c)=>Padding(padding:const EdgeInsets.symmetric(horizontal:14,vertical:10),child:Row(children:[_SettingIcon(icon),const SizedBox(width:12),Expanded(child:Text(title,style:const TextStyle(fontSize:15,fontWeight:FontWeight.w800))),Switch(value:value,onChanged:changed,activeThumbColor:Colors.black,activeTrackColor:ui.OpenApp.lime)]));}
class _SettingIcon extends StatelessWidget{const _SettingIcon(this.icon);final IconData icon;@override Widget build(BuildContext c)=>Container(width:38,height:38,decoration:BoxDecoration(color:ui.OpenApp.lime.withValues(alpha:.16),shape:BoxShape.circle),child:Icon(icon,size:20,color:Colors.black));}